# lot_sqlite_web — sqlite-web served on a pure-asyncio HTTP loop.
#
# Why not `python3 -m sqlite_web` (werkzeug)? socketserver's selector poll
# loop corrupts the interpreter on this wasm kernel: after the first request,
# serve_forever dies with "XXX lineno/opcode" + SystemError('unknown opcode').
# asyncio's epoll event loop is the proven-stable path here (uvicorn/WebFuse
# serve fine on it), so we speak minimal HTTP/1.1 ourselves and call the
# Flask WSGI app inline — single-threaded by design; the page's web-view
# proxy serializes requests anyway.
#
# Default bind is 0.0.0.0: the page's "web view" panel reaches the guest via
# injected TCP to the guest's eth0 IP; loopback isn't routable from the page.
import asyncio
import io
import optparse
import sys
import urllib.parse


def run_wsgi(app, host, port, banner):
    async def handle(reader, writer):
        try:
            head = b''
            while b'\r\n\r\n' not in head:
                chunk = await reader.read(8192)
                if not chunk:
                    return
                head += chunk
            head, _, body = head.partition(b'\r\n\r\n')
            lines = head.decode('latin1').split('\r\n')
            parts = lines[0].split(' ')
            method = parts[0]
            target = parts[1] if len(parts) > 1 else '/'
            hdrs = {}
            for ln in lines[1:]:
                k, sep, v = ln.partition(':')
                if sep:
                    hdrs[k.strip().lower()] = v.strip()
            clen = int(hdrs.get('content-length') or 0)
            while len(body) < clen:
                chunk = await reader.read(65536)
                if not chunk:
                    break
                body += chunk
            path, _, query = target.partition('?')
            env = {
                'REQUEST_METHOD': method,
                'SCRIPT_NAME': '',
                'PATH_INFO': urllib.parse.unquote(path),
                'QUERY_STRING': query,
                'SERVER_NAME': host,
                'SERVER_PORT': str(port),
                'SERVER_PROTOCOL': 'HTTP/1.1',
                'REMOTE_ADDR': '10.0.2.100',
                'CONTENT_LENGTH': str(clen),
                'wsgi.version': (1, 0),
                'wsgi.url_scheme': 'http',
                'wsgi.input': io.BytesIO(body[:clen] if clen else b''),
                'wsgi.errors': sys.stderr,
                'wsgi.multithread': False,
                'wsgi.multiprocess': False,
                'wsgi.run_once': False,
            }
            if 'content-type' in hdrs:
                env['CONTENT_TYPE'] = hdrs['content-type']
            for k, v in hdrs.items():
                env['HTTP_' + k.upper().replace('-', '_')] = v
            sh = []

            def start_response(status, out_headers, exc_info=None):
                sh[:] = [status, out_headers]
                return lambda _b: None

            result = app(env, start_response)
            out = b''.join(bytes(c) for c in result)
            if hasattr(result, 'close'):
                result.close()
            if sh:
                status, out_headers = sh
            else:
                status, out_headers = '500 Internal Server Error', []
            resp = ['HTTP/1.1 %s' % status]
            have_len = False
            for k, v in out_headers:
                if k.lower() == 'content-length':
                    have_len = True
                resp.append('%s: %s' % (k, v))
            if not have_len:
                resp.append('Content-Length: %d' % len(out))
            resp.append('Connection: close')
            writer.write(('\r\n'.join(resp) + '\r\n\r\n').encode('latin1') + out)
            await writer.drain()
        except Exception as e:
            try:
                sys.stderr.write('[sqlite-web] request error: %r\n' % (e,))
            except Exception:
                pass
        finally:
            try:
                writer.close()
            except Exception:
                pass

    async def amain():
        server = await asyncio.start_server(handle, host, port)
        print(banner, flush=True)
        async with server:
            await server.serve_forever()

    asyncio.run(amain())


def main():
    p = optparse.OptionParser(usage='%prog [options] database.db')
    p.add_option('-H', '--host', default='0.0.0.0')
    p.add_option('-p', '--port', type='int', default=8080)
    p.add_option('-r', '--read-only', action='store_true', default=False)
    p.add_option('-x', '--no-browser', action='store_true',
                 help='(ignored; kept for sqlite-web CLI compatibility)')
    opts, args = p.parse_args()
    if not args:
        p.error('give at least one sqlite database file (try /root/demo.db)')
    from sqlite_web.sqlite_web import app, initialize_app
    initialize_app(args, opts.read_only)
    run_wsgi(app, opts.host, opts.port,
             'sqlite-web serving %s on http://%s:%d/ — top bar: web view'
             % (', '.join(args), opts.host, opts.port))


if __name__ == '__main__':
    main()
